#!/usr/bin/env bash
# Generated by HostKit. Do not edit manually.
# Product: ROUTER
# Platform: Alpine Linux

set -Eeuo pipefail

# ---- module: core ----
# HostKit Alpine core mechanisms.
# Sourcing this file must not change host or caller shell state.

log_info()  { printf 'INFO  %s\n' "$*"; }
log_warn()  { printf 'WARN  %s\n' "$*" >&2; }
log_error() { printf 'ERROR %s\n' "$*" >&2; }
log_ok()    { printf 'OK    %s\n' "$*"; }

die() { log_error "$*"; return 1; }

require_root() {
    [ "$(id -u)" -eq 0 ] || { die "HostKit must run as root."; return 1; }
}

require_command() {
    local command_name
    for command_name in "$@"; do
        command -v "$command_name" >/dev/null 2>&1 ||
            { die "Required command not found: $command_name"; return 1; }
    done
}

require_alpine() {
    [ -r /etc/os-release ] || { die "Cannot identify operating system."; return 1; }
    local id
    id="$(. /etc/os-release; printf '%s' "${ID:-}")"
    [ "$id" = "alpine" ] || { die "Unsupported operating system: Alpine Linux is required."; return 1; }
}

# ---- module: network ----
# Alpine network inspection mechanisms.

network_validate_interface_name() {
    [ -n "$1" ] && printf '%s' "$1" | grep -Eq '^[A-Za-z0-9_.:-]+$'
}

network_interface_exists() {
    network_validate_interface_name "$1" && ip link show dev "$1" >/dev/null 2>&1
}

network_detect_uplink() {
    local routes count
    routes="$(ip -4 route show default 2>/dev/null || true)"
    count="$(printf '%s\n' "$routes" | awk 'NF { n++ } END { print n+0 }')"
    [ "$count" -eq 1 ] || return 2
    printf '%s\n' "$routes" | awk '{ for (i=1;i<=NF;i++) if ($i=="dev") { print $(i+1); exit } }'
}

# ---- module: dhcp ----
# Alpine DHCPv4 validation mechanisms.

dhcp_validate_ipv4() {
    local value="$1" a b c d extra octet n
    IFS=. read -r a b c d extra <<EOF
$value
EOF
    [ -z "${extra:-}" ] || return 1
    for octet in "$a" "$b" "$c" "$d"; do
        case "$octet" in ''|*[!0-9]*) return 1 ;; esac
        [ "${#octet}" -eq 1 ] || [ "${octet#0}" = "$octet" ] || return 1
        n=$((10#$octet)); [ "$n" -le 255 ] || return 1
    done
}

dhcp_validate_ipv4_cidr() {
    local value="$1" address prefix
    case "$value" in */*) address="${value%/*}"; prefix="${value##*/}" ;; *) return 1 ;; esac
    dhcp_validate_ipv4 "$address" || return 1
    case "$prefix" in ''|*[!0-9]*) return 1 ;; esac
    [ "$((10#$prefix))" -le 30 ]
}

dhcp_validate_range() {
    local value="$1" first last
    case "$value" in *-*) first="${value%%-*}"; last="${value#*-}" ;; *) return 1 ;; esac
    dhcp_validate_ipv4 "$first" && dhcp_validate_ipv4 "$last" || return 1
    [ "$first" != "$last" ]
}

dhcp_ipv4_to_int() {
    local value="$1" a b c d
    dhcp_validate_ipv4 "$value" || return 1
    IFS=. read -r a b c d <<EOF
$value
EOF
    printf '%u\n' "$(( (10#$a << 24) + (10#$b << 16) + (10#$c << 8) + 10#$d ))"
}

dhcp_range_usable_for_lan() {
    local cidr="$1" range="$2" gateway prefix first last g f l mask network broadcast
    gateway="${cidr%/*}"; prefix="${cidr##*/}"; first="${range%%-*}"; last="${range#*-}"
    g="$(dhcp_ipv4_to_int "$gateway")" || return 1
    f="$(dhcp_ipv4_to_int "$first")" || return 1
    l="$(dhcp_ipv4_to_int "$last")" || return 1
    [ "$f" -lt "$l" ] || return 1
    mask=$(( (0xFFFFFFFF << (32 - 10#$prefix)) & 0xFFFFFFFF ))
    network=$((g & mask)); broadcast=$((network | ((~mask) & 0xFFFFFFFF)))
    [ $((f & mask)) -eq "$network" ] && [ $((l & mask)) -eq "$network" ] || return 1
    [ "$f" -ne "$network" ] && [ "$l" -ne "$broadcast" ] || return 1
    ! { [ "$g" -ge "$f" ] && [ "$g" -le "$l" ]; }
}

dhcp_cidr_network() {
    local cidr="$1" gateway prefix g mask network
    dhcp_validate_ipv4_cidr "$cidr" || return 1
    gateway="${cidr%/*}"; prefix="${cidr##*/}"
    g="$(dhcp_ipv4_to_int "$gateway")" || return 1
    mask=$(( (0xFFFFFFFF << (32 - 10#$prefix)) & 0xFFFFFFFF ))
    network=$((g & mask))
    printf '%u/%s\n' "$network" "$prefix"
}

# ---- module: pppoe ----
# Alpine PPPoE peer rendering and inspection.
# Secrets remain external and are never copied into router configuration.

pppoe_validate_user() {
    local user="$1"
    [ -n "$user" ] || return 1
    case "$user" in *$'\n'*|*$'\r'*|*$'\t'*) return 1 ;; esac
    case "$user" in
        *[!A-Za-z0-9._@:+/-]*) return 1 ;;
    esac
}

pppoe_validate_secret_file() {
    [ -f "$1" ] && [ -r "$1" ] && [ ! -L "$1" ]
}

pppoe_render_peer() {
    local uplink="$1" user="$2"
    network_validate_interface_name "$uplink" || return 1
    pppoe_validate_user "$user" || return 1
    cat <<EOF
# Managed by HostKit. Do not edit manually.
user "$user"
plugin pppoe.so $uplink
noipdefault
usepeerdns
defaultroute
persist
noauth
EOF
}

pppoe_is_active() {
    local interface="${1:-ppp0}"
    ip link show dev "$interface" >/dev/null 2>&1 &&
        ip -4 addr show dev "$interface" | grep -q 'inet '
}

pppoe_hostkit_owned() {
    local path="$1"
    [ -f "$path" ] && IFS= read -r first <"$path" &&
        [ "$first" = "# Managed by HostKit. Do not edit manually." ]
}

pppoe_install_peer() {
    local source="$1" path="${HOSTKIT_PPPOE_PEER_PATH:-/etc/ppp/peers/hostkit-router}"
    [ -r "$source" ] || { die "PPPoE peer source is not readable: $source"; return 1; }
    if [ -e "$path" ] && ! pppoe_hostkit_owned "$path"; then
        die "Refusing to overwrite PPPoE peer not owned by HostKit: $path"; return 1
    fi
    mkdir -p "$(dirname "$path")"
    if [ -f "$path" ] && cmp -s "$source" "$path"; then return 0; fi
    install -m 0600 "$source" "$path"
}

# ---- module: router-config ----
# Strict Alpine ROUTER KEY=VALUE parser.

router_config_reset() {
    UPLINK=; UPLINK_MODE=; LAN=; LAN_ADDRESS=; DHCP_RANGE=
    SECOND_LAN=; SECOND_LAN_ADDRESS=; SECOND_DHCP_RANGE=
    PPPOE_USER=; PPPOE_SECRET_FILE=
}

router_config_parse() {
    local path="$1" line key value seen="|"
    [ -r "$path" ] || { die "Router configuration is not readable: $path"; return 1; }
    router_config_reset
    while IFS= read -r line || [ -n "$line" ]; do
        case "$line" in ''|\#*) continue ;; esac
        case "$line" in *=*) ;; *) die "Invalid router configuration record."; return 1 ;; esac
        key="${line%%=*}"; value="${line#*=}"
        case "$key" in
            UPLINK|UPLINK_MODE|LAN|LAN_ADDRESS|DHCP_RANGE|SECOND_LAN|SECOND_LAN_ADDRESS|SECOND_DHCP_RANGE|PPPOE_USER|PPPOE_SECRET_FILE) ;;
            *) die "Unknown router configuration key: $key"; return 1 ;;
        esac
        case "$seen" in *"|$key|"*) die "Duplicate router configuration key: $key"; return 1 ;; esac
        case "$value" in *$'\n'*|*$'\r'*) die "Invalid router configuration value for $key"; return 1 ;; esac
        seen="${seen}$key|"; printf -v "$key" '%s' "$value"
    done <"$path"
}

router_config_validate() {
    local lan_network second_lan_network
    case "$UPLINK_MODE" in dhcp|pppoe) ;; *) die "UPLINK_MODE must be dhcp or pppoe."; return 1 ;; esac
    network_interface_exists "$UPLINK" || { die "Invalid UPLINK: $UPLINK"; return 1; }
    network_interface_exists "$LAN" || { die "Invalid LAN: $LAN"; return 1; }
    [ "$UPLINK" != "$LAN" ] || { die "UPLINK and LAN must be different."; return 1; }
    dhcp_validate_ipv4_cidr "$LAN_ADDRESS" || { die "Invalid LAN_ADDRESS."; return 1; }
    dhcp_validate_range "$DHCP_RANGE" || { die "Invalid DHCP_RANGE."; return 1; }
    dhcp_range_usable_for_lan "$LAN_ADDRESS" "$DHCP_RANGE" ||
        { die "DHCP_RANGE is not usable within LAN_ADDRESS."; return 1; }
    lan_network="$(dhcp_cidr_network "$LAN_ADDRESS")" || { die "Invalid LAN_ADDRESS."; return 1; }

    if [ -n "$SECOND_LAN" ] || [ -n "$SECOND_LAN_ADDRESS" ] || [ -n "$SECOND_DHCP_RANGE" ]; then
        [ -n "$SECOND_LAN" ] && [ -n "$SECOND_LAN_ADDRESS" ] && [ -n "$SECOND_DHCP_RANGE" ] ||
            { die "SECOND_LAN requires SECOND_LAN_ADDRESS and SECOND_DHCP_RANGE."; return 1; }
        network_interface_exists "$SECOND_LAN" || { die "Invalid SECOND_LAN: $SECOND_LAN"; return 1; }
        [ "$SECOND_LAN" != "$UPLINK" ] || { die "UPLINK and SECOND_LAN must be different."; return 1; }
        [ "$SECOND_LAN" != "$LAN" ] || { die "LAN and SECOND_LAN must be different."; return 1; }
        dhcp_validate_ipv4_cidr "$SECOND_LAN_ADDRESS" || { die "Invalid SECOND_LAN_ADDRESS."; return 1; }
        dhcp_validate_range "$SECOND_DHCP_RANGE" || { die "Invalid SECOND_DHCP_RANGE."; return 1; }
        dhcp_range_usable_for_lan "$SECOND_LAN_ADDRESS" "$SECOND_DHCP_RANGE" ||
            { die "SECOND_DHCP_RANGE is not usable within SECOND_LAN_ADDRESS."; return 1; }
        second_lan_network="$(dhcp_cidr_network "$SECOND_LAN_ADDRESS")" ||
            { die "Invalid SECOND_LAN_ADDRESS."; return 1; }
        [ "$lan_network" != "$second_lan_network" ] ||
            { die "LAN_ADDRESS and SECOND_LAN_ADDRESS must use different networks."; return 1; }
    fi

    if [ "$UPLINK_MODE" = pppoe ]; then
        pppoe_validate_user "$PPPOE_USER" || { die "Invalid PPPOE_USER."; return 1; }
        pppoe_validate_secret_file "$PPPOE_SECRET_FILE" || { die "Invalid PPPOE_SECRET_FILE."; return 1; }
    elif [ -n "$PPPOE_USER" ] || [ -n "$PPPOE_SECRET_FILE" ]; then
        die "PPPoE settings require UPLINK_MODE=pppoe."
        return 1
    fi
}

# ---- module: network-config ----
# Alpine ifupdown-ng managed network configuration.

network_config_hostkit_owned() {
    local path="$1"
    [ -f "$path" ] && IFS= read -r first <"$path" &&
        [ "$first" = "# Managed by HostKit. Do not edit manually." ]
}

network_config_render_dhcp() {
    local uplink="$1" lan="$2" lan_address="$3" second_lan="${4:-}" second_lan_address="${5:-}"
    cat <<EOF
# Managed by HostKit. Do not edit manually.
auto $uplink
iface $uplink inet dhcp

auto $lan
iface $lan inet static
    address $lan_address
EOF
    if [ -n "$second_lan" ]; then
        cat <<EOF

auto $second_lan
iface $second_lan inet static
    address $second_lan_address
EOF
    fi
}

network_config_render_pppoe_lan() {
    local lan="$1" lan_address="$2" second_lan="${3:-}" second_lan_address="${4:-}"
    cat <<EOF
# Managed by HostKit. Do not edit manually.
auto $lan
iface $lan inet static
    address $lan_address
EOF
    if [ -n "$second_lan" ]; then
        cat <<EOF

auto $second_lan
iface $second_lan inet static
    address $second_lan_address
EOF
    fi
}

network_config_install() {
    local source="$1" path="${HOSTKIT_INTERFACES_PATH:-/etc/network/interfaces.d/90-hostkit-router}"
    [ -r "$source" ] || { die "Network source file is not readable: $source"; return 1; }
    mkdir -p "$(dirname "$path")"
    if [ -e "$path" ] && ! network_config_hostkit_owned "$path"; then
        die "Refusing to overwrite network file not owned by HostKit: $path"; return 1
    fi
    if [ -f "$path" ] && cmp -s "$source" "$path"; then return 0; fi
    install -m 0644 "$source" "$path"
}

# ---- module: forwarding ----
# Alpine forwarding mechanisms.

forwarding_ipv4_enabled() { [ "$(sysctl -n net.ipv4.ip_forward 2>/dev/null)" = 1 ]; }
forwarding_ipv6_enabled() { [ "$(sysctl -n net.ipv6.conf.all.forwarding 2>/dev/null)" = 1 ]; }

forwarding_set_ipv4() { sysctl -q -w net.ipv4.ip_forward="$1" >/dev/null; }

forwarding_hostkit_owned() {
    local path="$1"
    [ -f "$path" ] && IFS= read -r first <"$path" &&
        [ "$first" = "# Managed by HostKit. Do not edit manually." ]
}

forwarding_write_persistent() {
    local ipv4="$1" ipv6="$2"
    local path="${HOSTKIT_SYSCTL_FILE:-/etc/sysctl.d/90-hostkit-router.conf}"
    case "$ipv4:$ipv6" in 0:0|0:1|1:0|1:1) ;; *) die "Invalid forwarding state."; return 1 ;; esac

    if [ -e "$path" ] && ! forwarding_hostkit_owned "$path"; then
        die "Refusing to overwrite sysctl file not owned by HostKit: $path"
        return 1
    fi

    mkdir -p "$(dirname "$path")"
    local tmp
    tmp="$(mktemp)"
    {
        printf '# Managed by HostKit. Do not edit manually.\n'
        printf 'net.ipv4.ip_forward = %s\n' "$ipv4"
        printf 'net.ipv6.conf.all.forwarding = %s\n' "$ipv6"
    } >"$tmp"

    if [ -f "$path" ] && cmp -s "$tmp" "$path"; then rm -f "$tmp"; return 0; fi
    install -m 0644 "$tmp" "$path"
    rm -f "$tmp"
}

# ---- module: nftables ----
# Alpine nftables mechanisms.

nftables_validate_file() { nft -c -f "$1"; }
nftables_apply_file() { nft -f "$1"; }

# ---- module: router-firewall ----
# Alpine ROUTER nftables policy renderer.

router_firewall_validate_interface_name() {
    network_validate_interface_name "$1"
}

router_firewall_render_unchecked() {
    local lan="$1" wan="$2" second_lan="${3:-}"
    router_firewall_validate_interface_name "$lan" || { die "Invalid LAN interface: $lan"; return 1; }
    router_firewall_validate_interface_name "$wan" || { die "Invalid WAN interface: $wan"; return 1; }
    [ "$lan" != "$wan" ] || { die "LAN and WAN interfaces must be different."; return 1; }
    if [ -n "$second_lan" ]; then
        router_firewall_validate_interface_name "$second_lan" || { die "Invalid SECOND_LAN interface: $second_lan"; return 1; }
        [ "$second_lan" != "$wan" ] || { die "SECOND_LAN and WAN interfaces must be different."; return 1; }
        [ "$second_lan" != "$lan" ] || { die "LAN and SECOND_LAN interfaces must be different."; return 1; }
    fi

    cat <<EOF
table inet hostkit_router {
    chain forward {
        type filter hook forward priority 0; policy drop;
        ct state invalid drop
        ct state established,related accept
        iifname "$lan" oifname "$wan" accept
EOF
    if [ -n "$second_lan" ]; then
        cat <<EOF
        iifname "$second_lan" oifname "$wan" accept
EOF
    fi
    cat <<EOF
    }
}
table ip hostkit_router_nat {
    chain postrouting {
        type nat hook postrouting priority srcnat; policy accept;
        oifname "$wan" masquerade
    }
}
EOF
}

router_firewall_render_pppoe_unchecked() {
    local lan="$1" wan="$2" second_lan="${3:-}"
    router_firewall_validate_interface_name "$lan" || { die "Invalid LAN interface: $lan"; return 1; }
    router_firewall_validate_interface_name "$wan" || { die "Invalid WAN interface: $wan"; return 1; }
    [ "$lan" != "$wan" ] || { die "LAN and WAN interfaces must be different."; return 1; }
    if [ -n "$second_lan" ]; then
        router_firewall_validate_interface_name "$second_lan" || { die "Invalid SECOND_LAN interface: $second_lan"; return 1; }
        [ "$second_lan" != "$wan" ] || { die "SECOND_LAN and WAN interfaces must be different."; return 1; }
        [ "$second_lan" != "$lan" ] || { die "LAN and SECOND_LAN interfaces must be different."; return 1; }
    fi

    cat <<EOF
table inet hostkit_router {
    chain forward {
        type filter hook forward priority 0; policy drop;
        ct state invalid drop
        ct state established,related accept
        oifname "$wan" tcp flags syn tcp option maxseg size set rt mtu
        iifname "$lan" oifname "$wan" accept
EOF
    if [ -n "$second_lan" ]; then
        cat <<EOF
        iifname "$second_lan" oifname "$wan" accept
EOF
    fi
    cat <<EOF
    }
}
table ip hostkit_router_nat {
    chain postrouting {
        type nat hook postrouting priority srcnat; policy accept;
        oifname "$wan" masquerade
    }
}
EOF
}

router_firewall_render() {
    local lan="$1" wan="$2" second_lan="${3:-}"
    network_interface_exists "$lan" || { die "Invalid LAN interface: $lan"; return 1; }
    network_interface_exists "$wan" || { die "Invalid WAN interface: $wan"; return 1; }
    if [ -n "$second_lan" ]; then
        network_interface_exists "$second_lan" || { die "Invalid SECOND_LAN interface: $second_lan"; return 1; }
    fi
    router_firewall_render_unchecked "$lan" "$wan" "$second_lan"
}

router_firewall_render_pppoe() {
    local lan="$1" wan="$2" second_lan="${3:-}"
    network_interface_exists "$lan" || { die "Invalid LAN interface: $lan"; return 1; }
    network_interface_exists "$wan" || { die "Invalid WAN interface: $wan"; return 1; }
    if [ -n "$second_lan" ]; then
        network_interface_exists "$second_lan" || { die "Invalid SECOND_LAN interface: $second_lan"; return 1; }
    fi
    router_firewall_render_pppoe_unchecked "$lan" "$wan" "$second_lan"
}

# ---- module: router-nftables ----
# Alpine persistent nftables ownership.

router_nftables_hostkit_owned() {
    local path="$1"
    [ -f "$path" ] && IFS= read -r first <"$path" &&
        [ "$first" = "# Managed by HostKit. Do not edit manually." ]
}

router_nftables_install() {
    local source="$1" path="${HOSTKIT_NFT_PATH:-/etc/nftables.d/90-hostkit-router.nft}"
    nftables_validate_file "$source" || { die "Invalid nftables ruleset."; return 1; }
    mkdir -p "$(dirname "$path")"
    if [ -e "$path" ] && ! router_nftables_hostkit_owned "$path"; then
        die "Refusing to overwrite nftables file not owned by HostKit: $path"; return 1
    fi
    local tmp; tmp="$(mktemp)"
    { printf '%s\n' '# Managed by HostKit. Do not edit manually.'; cat "$source"; } >"$tmp"
    if [ -f "$path" ] && cmp -s "$tmp" "$path"; then rm -f "$tmp"; return 0; fi
    install -m 0644 "$tmp" "$path"
    rm -f "$tmp"
}

# ---- module: dnsmasq ----
# Alpine dnsmasq managed configuration.

dnsmasq_hostkit_owned() {
    local path="$1"
    [ -f "$path" ] && IFS= read -r first <"$path" &&
        [ "$first" = "# Managed by HostKit. Do not edit manually." ]
}

dnsmasq_render() {
    local lan="$1" lan_address="$2" range="$3" second_lan="${4:-}" second_lan_address="${5:-}" second_range="${6:-}"
    local gateway="${lan_address%/*}"
    local first="${range%%-*}" last="${range#*-}"
    if [ -z "$second_lan" ]; then
        cat <<EOF
# Managed by HostKit. Do not edit manually.
interface=$lan
bind-interfaces
dhcp-range=$first,$last,12h
dhcp-option=option:router,$gateway
dhcp-option=option:dns-server,$gateway
EOF
        return
    fi

    cat <<EOF
# Managed by HostKit. Do not edit manually.
interface=$lan
interface=$second_lan
bind-interfaces
dhcp-range=set:$lan,$first,$last,12h
dhcp-option=tag:$lan,option:router,$gateway
dhcp-option=tag:$lan,option:dns-server,$gateway
EOF
    gateway="${second_lan_address%/*}"
    first="${second_range%%-*}"; last="${second_range#*-}"
    cat <<EOF
dhcp-range=set:$second_lan,$first,$last,12h
dhcp-option=tag:$second_lan,option:router,$gateway
dhcp-option=tag:$second_lan,option:dns-server,$gateway
EOF
}

dnsmasq_validate() { dnsmasq --test --conf-file="$1" >/dev/null 2>&1; }

dnsmasq_install() {
    local source="$1" path="${HOSTKIT_DNSMASQ_PATH:-/etc/dnsmasq.d/90-hostkit-router.conf}"
    dnsmasq_validate "$source" || { die "Invalid dnsmasq configuration."; return 1; }
    mkdir -p "$(dirname "$path")"
    if [ -e "$path" ] && ! dnsmasq_hostkit_owned "$path"; then
        die "Refusing to overwrite dnsmasq file not owned by HostKit: $path"; return 1
    fi
    if [ -f "$path" ] && cmp -s "$source" "$path"; then return 0; fi
    install -m 0644 "$source" "$path"
}

# ---- product: router ----
# HostKit Alpine ROUTER product definition.
# Live configured takeover remains gated on Alpine VM validation.

MODULES=(
    core
    network
    dhcp
    pppoe
    router-config
    network-config
    forwarding
    nftables
    router-firewall
    router-nftables
    dnsmasq
)

hostkit_main() {
    require_root
    require_alpine
    require_command ip sysctl nft grep awk mktemp install cmp

    if [ "$#" -eq 0 ]; then
        local uplink rc=0 ipv6=0
        uplink="$(network_detect_uplink)" || rc=$?
        case "$rc" in
            0) ;;
            2) die "Multiple or missing IPv4 default-route uplinks; refusing to guess."; return 1 ;;
            *) die "Unable to detect uplink."; return 1 ;;
        esac
        forwarding_ipv6_enabled && ipv6=1
        forwarding_write_persistent 1 "$ipv6"
        forwarding_set_ipv4 1
        forwarding_ipv4_enabled || { die "IPv4 forwarding could not be enabled."; return 1; }
        log_ok "IPv4 forwarding enabled."
        log_info "Detected preserved uplink: $uplink"
        log_warn "No configuration supplied; network ownership was not changed."
        log_ok "Alpine ROUTER preserve-existing-uplink preparation completed."
        return 0
    fi

    [ "$#" -eq 2 ] && [ "$1" = "--check" ] || {
        die "Usage: alpine-router.sh [--check ROUTER_CONFIG]"
        return 2
    }

    router_config_parse "$2"
    router_config_validate

    local d network_file dnsmasq_file nft_file wan_for_firewall
    d="$(mktemp -d)"
    network_file="$d/interfaces"
    dnsmasq_file="$d/dnsmasq.conf"
    nft_file="$d/router.nft"

    if [ "$UPLINK_MODE" = dhcp ]; then
        network_config_render_dhcp "$UPLINK" "$LAN" "$LAN_ADDRESS" "$SECOND_LAN" "$SECOND_LAN_ADDRESS" >"$network_file"
        wan_for_firewall="$UPLINK"
    else
        network_config_render_pppoe_lan "$LAN" "$LAN_ADDRESS" "$SECOND_LAN" "$SECOND_LAN_ADDRESS" >"$network_file"
        pppoe_render_peer "$UPLINK" "$PPPOE_USER" >"$d/pppoe-peer"
        wan_for_firewall=ppp0
    fi
    dnsmasq_render "$LAN" "$LAN_ADDRESS" "$DHCP_RANGE" "$SECOND_LAN" "$SECOND_LAN_ADDRESS" "$SECOND_DHCP_RANGE" >"$dnsmasq_file"

    # ppp0 may not exist before PPPoE is started, so render validation only
    # requires interface syntax for that future runtime interface.
    if [ "$UPLINK_MODE" = pppoe ]; then
        router_firewall_render_pppoe_unchecked "$LAN" "$wan_for_firewall" "$SECOND_LAN" >"$nft_file"
    else
        router_firewall_render "$LAN" "$wan_for_firewall" "$SECOND_LAN" >"$nft_file"
    fi

    require_command dnsmasq
    dnsmasq_validate "$dnsmasq_file" || { rm -rf "$d"; die "Generated dnsmasq configuration is invalid."; return 1; }
    nftables_validate_file "$nft_file" || { rm -rf "$d"; die "Generated nftables ruleset is invalid."; return 1; }
    rm -rf "$d"

    log_ok "Router configuration is valid."
    log_info "UPLINK_MODE=$UPLINK_MODE UPLINK=$UPLINK LAN=$LAN LAN_ADDRESS=$LAN_ADDRESS"
    if [ -n "$SECOND_LAN" ]; then
        log_info "SECOND_LAN=$SECOND_LAN SECOND_LAN_ADDRESS=$SECOND_LAN_ADDRESS"
    fi
    log_warn "Check mode does not write files, restart services, or change live networking."
}

hostkit_main "$@"
